const item = $input.first().json;

// --------------------
// 1. Extract raw input safely
// --------------------
const raw =
  typeof item.text === 'string'
    ? item.text
    : typeof item.output === 'string'
      ? item.output
      : typeof item.output === 'object'
        ? JSON.stringify(item.output)
        : '';

// --------------------
// 2. Clean markdown / code fences
// --------------------
let stripped = String(raw)
  .replace(/```(?:json)?/gi, '')
  .replace(/```/g, '')
  .trim();

// --------------------
// 3. Parse JSON safely
// --------------------
let data = null;

try {
  data = JSON.parse(stripped);
} catch (e) {
  const match = stripped.match(/{[\s\S]*}/);
  if (match) {
    try {
      data = JSON.parse(match[0]);
    } catch (e2) {
      data = null;
    }
  }
}

// --------------------
// 4. Helpers
// --------------------
function norm(v, limit = 5) {
  if (Array.isArray(v)) {
    return v.slice(0, limit).map(String);
  }

  if (typeof v === 'string') {
    return v
      .split(',')
      .map(s => s.trim())
      .filter(Boolean)
      .slice(0, limit);
  }

  if (v == null || v === '') return [];

  return [String(v)];
}

function toInt(v) {
  const n = parseInt(v, 10);
  return isNaN(n) ? null : n;
}

// 💰 FIX: handles "₪2,450,000" or "2,450,000" or "$120000"
function parsePrice(v) {
  if (!v) return null;
  const cleaned = String(v).replace(/[^\d]/g, '');
  return cleaned ? Number(cleaned) : null;
}

// --------------------
// 5. Validate input
// --------------------
if (!data || typeof data !== 'object') {
  return [{
    json: {
      output: null,
      extract_error: true,
      raw_preview: String(raw).slice(0, 500),
    }
  }];
}

// --------------------
// 6. Normalize output (FIXED MAPPINGS)
// --------------------
const output = {
  property_type: data.property_type ?? 'other',
  location: data.location ?? '',

  // FIX: supports both price formats
  price_ils: parsePrice(data.price_ils ?? data.price),

  // FIX: supports both field names
  num_rooms: toInt(data.num_rooms ?? data.number_of_rooms),

  key_features: norm(data.key_features),

  certifications: data.certifications ? String(data.certifications) : '',
};

// --------------------
// 7. Return final result
// --------------------
return [{ json: { output } }];

const item = $input.first().json;

// 1. Get raw input safely
let raw =
  typeof item.text === 'string'
    ? item.text
    : typeof item.output === 'string'
      ? item.output
      : typeof item === 'string'
        ? item
        : '';

// 2. Remove markdown code fences (robust)
let stripped = String(raw)
  .replace(/```(?:json)?/gi, '')
  .replace(/```/g, '')
  .trim();

// 3. Try direct JSON parse first
let data = null;

try {
  data = JSON.parse(stripped);
} catch (e) {

  // 4. Try to extract JSON block from messy output
  const match = stripped.match(/\{[\s\S]*\}/);

  if (match) {
    try {
      data = JSON.parse(match[0]);
    } catch (e2) {
      data = null;
    }
  }
}

// 5. If wrapped inside { report: {...} }, unwrap it
if (data && typeof data === 'object' && data.report && typeof data.report === 'object') {
  data = data.report;
}

// 6. Fallback safe structure
const fallback = {
  property_type: 'unknown',
  routing_decision: 'residential',
  location: 'unknown',
  price_ils: null,
  num_rooms: null,
  key_features: [],
  image_scores: [],
  similar_listings: [],
  rag_insight: '',
  enrichment_notes: 'Could not parse final report JSON from LLM output.',
  confidence: 0,
  parse_error: true,
};

// 7. Final response
if (!data || typeof data !== 'object') {
  return [{
    json: {
      ...fallback,
      raw_preview: String(raw).slice(0, 800),
    }
  }];
}

return [{
  json: data
}];
